ALTER TABLE ccpun_admin.analytics_completed_report DROP CONSTRAINT analytics_completed_report_report_check;
ALTER TABLE ccpun_admin.analytics_completed_report ADD CONSTRAINT analytics_completed_report_report_check CHECK(report IN('gsc-summary','gsc-query-page','ga4-summary','ga4-organic-landing','ga4-session-performance','ga4-marketing-events','social-performance','seo-intelligence','ubersuggest-web-keywords','gsc-daily-page','gsc-daily-query-page','ga4-daily-organic','ga4-content-events'));
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_asset (
 asset_id text PRIMARY KEY, canonical_url text UNIQUE, title text NOT NULL, category text, topic text, search_intent text, content_type text NOT NULL, published_at timestamptz, publication_status text, source_revision text, updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_asset_alias (
 url text PRIMARY KEY, asset_id text NOT NULL REFERENCES ccpun_admin.marketing_asset(asset_id), mapping_method text NOT NULL CHECK(mapping_method IN('sanity-canonical','sanity-legacy','site-route')), mapping_version text NOT NULL DEFAULT 'identity-v1', updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_report_manifest (
 batch_id uuid NOT NULL REFERENCES ccpun_admin.analytics_daily_batch(batch_id), report text NOT NULL, resource_scope text NOT NULL, period_start date, period_end date, source_as_of_date date, source_as_of_ts timestamptz, source_as_of text, collected_at timestamptz NOT NULL, source_timezone text, raw_sha256 text NOT NULL CHECK(raw_sha256~'^[0-9a-f]{64}$'), complete boolean NOT NULL, limitations jsonb NOT NULL CHECK(jsonb_typeof(limitations)='array'), definition_version text NOT NULL DEFAULT 'marketing-v1', PRIMARY KEY(batch_id,report)
);
CREATE INDEX IF NOT EXISTS marketing_manifest_window ON ccpun_admin.marketing_report_manifest(report,resource_scope,period_end,collected_at DESC);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_gsc_daily (
 batch_id uuid NOT NULL, report text NOT NULL CHECK(report IN('gsc-daily-page','gsc-daily-query-page')), resource_scope text NOT NULL, day date NOT NULL, page text NOT NULL, query text NOT NULL DEFAULT '', clicks numeric NOT NULL CHECK(clicks>=0), impressions numeric NOT NULL CHECK(impressions>=0), average_position numeric CHECK(average_position>=0), PRIMARY KEY(batch_id,report,day,page,query), FOREIGN KEY(batch_id,report) REFERENCES ccpun_admin.marketing_report_manifest(batch_id,report), CHECK(report<>'gsc-daily-page' OR query='')
);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_ga4_acquisition_daily (
 batch_id uuid NOT NULL, report text NOT NULL CHECK(report IN('ga4-daily-organic','ga4-session-performance')), resource_scope text NOT NULL, day date NOT NULL, source_medium text NOT NULL, campaign text NOT NULL, landing_page text NOT NULL, sessions bigint NOT NULL CHECK(sessions>=0), engaged_sessions bigint NOT NULL CHECK(engaged_sessions BETWEEN 0 AND sessions), key_events numeric CHECK(key_events>=0), session_key_event_rate numeric CHECK(session_key_event_rate BETWEEN 0 AND 1), PRIMARY KEY(batch_id,report,day,source_medium,campaign,landing_page), FOREIGN KEY(batch_id,report) REFERENCES ccpun_admin.marketing_report_manifest(batch_id,report)
);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_ga4_event_daily (
 batch_id uuid NOT NULL, report text NOT NULL CHECK(report IN('ga4-content-events','ga4-marketing-events')), resource_scope text NOT NULL, day date NOT NULL, event_name text NOT NULL, page text NOT NULL, event_count bigint NOT NULL CHECK(event_count>=0), PRIMARY KEY(batch_id,report,day,event_name,page), FOREIGN KEY(batch_id,report) REFERENCES ccpun_admin.marketing_report_manifest(batch_id,report), CHECK(report<>'ga4-marketing-events' OR page='')
);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_social_snapshot (
 batch_id uuid NOT NULL REFERENCES ccpun_admin.analytics_daily_batch(batch_id), platform text NOT NULL CHECK(platform IN('Facebook','Instagram')), object_id text NOT NULL, captured_at timestamptz NOT NULL, published_at timestamptz, url text, content_type text, views numeric CHECK(views>=0), reach numeric CHECK(reach>=0), interactions numeric CHECK(interactions>=0), shares numeric CHECK(shares>=0), saves numeric CHECK(saves>=0), PRIMARY KEY(batch_id,platform,object_id)
);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_metric_rule (
 metric text PRIMARY KEY, minimum_volume numeric NOT NULL CHECK(minimum_volume>0), minimum_previous numeric NOT NULL CHECK(minimum_previous>0), decline_percent numeric NOT NULL CHECK(decline_percent BETWEEN 1 AND 100), version text NOT NULL DEFAULT 'rules-v1'
);
