CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_action (
 action_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version integer NOT NULL DEFAULT 1 CHECK(version>0), asset_id text REFERENCES ccpun_admin.marketing_asset(asset_id), priority text NOT NULL CHECK(priority IN('high','medium','low')), action_type text NOT NULL CHECK(action_type IN('title','description','refresh','cta','internal_link','expansion','promotion','keyword','investigation')), description text NOT NULL CHECK(length(description) BETWEEN 1 AND 2000), expected_metric text NOT NULL REFERENCES ccpun_admin.marketing_metric_rule(metric), owner text NOT NULL CHECK(length(owner)<=160), status text NOT NULL CHECK(status IN('backlog','planned','doing','measuring','done')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), executed_at timestamptz, baseline_value numeric, baseline_manifest jsonb, baseline_covered boolean NOT NULL DEFAULT false, measurement_days integer NOT NULL CHECK(measurement_days BETWEEN 7 AND 90), notes text NOT NULL CHECK(length(notes)<=2000), hypothesis text NOT NULL CHECK(length(hypothesis)<=1000), confounder_notes text NOT NULL CHECK(length(confounder_notes)<=2000), CHECK(status NOT IN('measuring','done') OR executed_at IS NOT NULL)
);
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_action_revision (action_id uuid NOT NULL REFERENCES ccpun_admin.marketing_action(action_id),version integer NOT NULL,record jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(action_id,version));
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_project_report(p_batch uuid,p_report text,p_data jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $project$
DECLARE r jsonb; scope text:=coalesce(nullif(p_data->>'resourceScope',''),(SELECT substring(request_meta->>'path' FROM '/properties/([0-9]+):') FROM ccpun_admin.analytics_raw_page WHERE batch_id=p_batch AND report=p_report LIMIT 1),'legacy-unverified'); complete boolean;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM ccpun_admin.analytics_daily_batch WHERE batch_id=p_batch AND status IN('running','completed')) THEN RAISE EXCEPTION 'MARKETING_BATCH_INVALID'; END IF;
 complete:=NOT coalesce((p_data->>'truncated')::boolean,true) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p_data->'limitations','[]'::jsonb)) x WHERE x~*'threshold|sampled|other.row loss|grouped rows');
 INSERT INTO ccpun_admin.marketing_report_manifest(batch_id,report,resource_scope,period_start,period_end,source_as_of_date,source_as_of_ts,source_as_of,collected_at,source_timezone,raw_sha256,complete,limitations) VALUES(p_batch,p_report,scope,(p_data->>'windowStart')::date,(p_data->>'windowEnd')::date,CASE WHEN p_data->>'sourceAsOf'~'^\d{4}-\d{2}-\d{2}$' THEN (p_data->>'sourceAsOf')::date ELSE (p_data->>'sourceAsOf')::timestamptz::date END,CASE WHEN p_data->>'sourceAsOf'~'^\d{4}-\d{2}-\d{2}$' THEN NULL ELSE (p_data->>'sourceAsOf')::timestamptz END,p_data->>'sourceAsOf',(p_data->>'collectedAt')::timestamptz,p_data->>'nativeTimeZone',p_data->>'rawHash',complete,coalesce(p_data->'limitations','[]')) ON CONFLICT DO NOTHING;
 FOR r IN SELECT value FROM jsonb_array_elements(p_data->'rows') LOOP
  IF p_report IN('gsc-daily-page','gsc-daily-query-page') THEN
   INSERT INTO ccpun_admin.marketing_gsc_daily VALUES(p_batch,p_report,scope,(r->>'วันที่')::date,split_part(split_part(r->>'หน้าเว็บ','?',1),'#',1),coalesce(r->>'คำค้น',''),(r->>'คลิก')::numeric,(r->>'การแสดงผล')::numeric,(r->>'อันดับเฉลี่ย')::numeric) ON CONFLICT DO NOTHING;
  ELSIF p_report IN('ga4-daily-organic','ga4-session-performance') THEN
   INSERT INTO ccpun_admin.marketing_ga4_acquisition_daily VALUES(p_batch,p_report,scope,(r->>'วันที่')::date,coalesce(r->>'แหล่งทราฟฟิก / Medium','Organic Search'),coalesce(r->>'แคมเปญ',''),r->>'หน้าเข้า',(r->>'เซสชัน')::bigint,(r->>'Engaged sessions')::bigint,(r->>'Key events')::numeric,(r->>'Session key event rate (%)')::numeric/100) ON CONFLICT DO NOTHING;
  ELSIF p_report IN('ga4-content-events','ga4-marketing-events') THEN
   INSERT INTO ccpun_admin.marketing_ga4_event_daily VALUES(p_batch,p_report,scope,(r->>'วันที่')::date,r->>'Event',coalesce(r->>'หน้าเว็บ',''),(r->>'จำนวน event')::bigint) ON CONFLICT DO NOTHING;
  ELSIF p_report='social-performance' THEN
   INSERT INTO ccpun_admin.marketing_asset(asset_id,title,content_type,published_at,publication_status,source_revision) VALUES('social:'||(r->>'แพลตฟอร์ม')||':'||(r->>'Provider Object ID'),r->>'Provider Object ID',coalesce(r->>'รูปแบบ','social'),(r->>'วันที่เผยแพร่ (UTC)')::timestamptz,'published','provider-object-v1') ON CONFLICT(asset_id) DO UPDATE SET content_type=excluded.content_type,published_at=excluded.published_at;
   INSERT INTO ccpun_admin.marketing_social_snapshot VALUES(p_batch,r->>'แพลตฟอร์ม',r->>'Provider Object ID',(p_data->>'collectedAt')::timestamptz,(r->>'วันที่เผยแพร่ (UTC)')::timestamptz,r->>'ลิงก์โพสต์',r->>'รูปแบบ',(r->>'ยอดดู')::numeric,(r->>'Reach')::numeric,(r->>'Total interactions')::numeric,(r->>'แชร์')::numeric,(r->>'บันทึก')::numeric) ON CONFLICT DO NOTHING;
  END IF;
 END LOOP;
END $project$;
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_report_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $trigger$ BEGIN PERFORM ccpun_admin.marketing_project_report(NEW.batch_id,NEW.report,NEW.data); RETURN NEW; END $trigger$;
DROP TRIGGER IF EXISTS marketing_project_report ON ccpun_admin.analytics_completed_report;
CREATE TRIGGER marketing_project_report AFTER INSERT ON ccpun_admin.analytics_completed_report FOR EACH ROW EXECUTE FUNCTION ccpun_admin.marketing_report_trigger();
-- Project existing native daily records only; never split historical rolling aggregates into days.
SELECT ccpun_admin.marketing_project_report(r.batch_id,r.report,r.data) FROM ccpun_admin.analytics_completed_report r JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.status='completed';
CREATE INDEX IF NOT EXISTS marketing_gsc_day_scope ON ccpun_admin.marketing_gsc_daily(resource_scope,report,day,page);
CREATE INDEX IF NOT EXISTS marketing_ga4_day_scope ON ccpun_admin.marketing_ga4_acquisition_daily(resource_scope,report,day,landing_page);
CREATE INDEX IF NOT EXISTS marketing_event_day_scope ON ccpun_admin.marketing_ga4_event_daily(resource_scope,report,day,event_name,page);
CREATE OR REPLACE VIEW ccpun_admin.marketing_gsc_current AS SELECT f.* FROM ccpun_admin.marketing_gsc_daily f JOIN ccpun_admin.marketing_report_manifest m USING(batch_id,report) JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.status='completed' AND m.complete AND NOT EXISTS(SELECT 1 FROM ccpun_admin.marketing_report_manifest newer JOIN ccpun_admin.analytics_daily_batch nb ON nb.batch_id=newer.batch_id WHERE nb.status='completed' AND newer.complete AND newer.resource_scope=f.resource_scope AND newer.report=f.report AND f.day BETWEEN newer.period_start AND newer.period_end AND (newer.collected_at,newer.batch_id)>(m.collected_at,m.batch_id));
CREATE OR REPLACE VIEW ccpun_admin.marketing_ga4_current AS SELECT f.* FROM ccpun_admin.marketing_ga4_acquisition_daily f JOIN ccpun_admin.marketing_report_manifest m USING(batch_id,report) JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.status='completed' AND m.complete AND NOT EXISTS(SELECT 1 FROM ccpun_admin.marketing_report_manifest newer JOIN ccpun_admin.analytics_daily_batch nb ON nb.batch_id=newer.batch_id WHERE nb.status='completed' AND newer.complete AND newer.resource_scope=f.resource_scope AND newer.report=f.report AND f.day BETWEEN newer.period_start AND newer.period_end AND (newer.collected_at,newer.batch_id)>(m.collected_at,m.batch_id));
CREATE OR REPLACE VIEW ccpun_admin.marketing_event_current AS SELECT f.* FROM ccpun_admin.marketing_ga4_event_daily f JOIN ccpun_admin.marketing_report_manifest m USING(batch_id,report) JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.status='completed' AND m.complete AND NOT EXISTS(SELECT 1 FROM ccpun_admin.marketing_report_manifest newer JOIN ccpun_admin.analytics_daily_batch nb ON nb.batch_id=newer.batch_id WHERE nb.status='completed' AND newer.complete AND newer.resource_scope=f.resource_scope AND newer.report=f.report AND f.day BETWEEN newer.period_start AND newer.period_end AND (newer.collected_at,newer.batch_id)>(m.collected_at,m.batch_id));
CREATE OR REPLACE VIEW ccpun_admin.marketing_daily_metric AS
 SELECT day,'organic_sessions'::text metric,landing_page asset_url,sessions::numeric value,batch_id,report,resource_scope FROM ccpun_admin.marketing_ga4_current WHERE report='ga4-daily-organic'
 UNION ALL SELECT day,'search_clicks',page,clicks,batch_id,report,resource_scope FROM ccpun_admin.marketing_gsc_current WHERE report='gsc-daily-page'
 UNION ALL SELECT day,'search_impressions',page,impressions,batch_id,report,resource_scope FROM ccpun_admin.marketing_gsc_current WHERE report='gsc-daily-page'
 UNION ALL SELECT day,CASE WHEN event_name='line_oa_click' THEN 'line_clicks' ELSE 'calculator_complete' END,page,event_count,batch_id,report,resource_scope FROM ccpun_admin.marketing_event_current WHERE report='ga4-content-events' AND event_name IN('line_oa_click','ci_calculator_complete','fhc_complete');
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_canonical_url(p text) RETURNS text LANGUAGE sql IMMUTABLE AS $url$ SELECT CASE WHEN p~'^/' THEN 'https://ccpun.com'||coalesce(nullif(rtrim(split_part(split_part(p,'?',1),'#',1),'/'),''),'/') WHEN p~'^https?://(www\.)?ccpun\.com(/|$)|^https?://blog\.ccpun\.com(/|$)' THEN regexp_replace(regexp_replace(rtrim(split_part(split_part(p,'?',1),'#',1),'/'),'^http://','https://'),'^https://www\.','https://') ELSE NULL END $url$;
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_window(p_key text,p_end date) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $window$
DECLARE s date; e date:=p_end; ps date; pe date;
BEGIN
 CASE p_key WHEN 'rolling_7' THEN s:=e-6; WHEN 'rolling_28' THEN s:=e-27; WHEN 'this_week' THEN s:=date_trunc('week',e::timestamp)::date; WHEN 'last_week' THEN e:=date_trunc('week',e::timestamp)::date-1;s:=e-6; WHEN 'this_month' THEN s:=date_trunc('month',e::timestamp)::date; WHEN 'last_month' THEN e:=date_trunc('month',e::timestamp)::date-1;s:=date_trunc('month',e::timestamp)::date; ELSE RAISE EXCEPTION 'INVALID_MARKETING_WINDOW'; END CASE;
 IF p_key='this_month' THEN ps:=(s-interval '1 month')::date;pe:=least(s-1,ps+(e-s)); ELSE pe:=s-1;ps:=pe-(e-s); END IF;
 RETURN jsonb_build_object('key',p_key,'currentStart',s,'currentEnd',e,'previousStart',ps,'previousEnd',pe,'calendarPolicy','Monday-start; provider-native dates; common mature cutoff; MTD equal elapsed days');
END $window$;
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_coverage(p_report text,p_start date,p_end date) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,ccpun_admin AS $coverage$
 SELECT NOT EXISTS(SELECT 1 FROM generate_series(p_start,p_end,interval '1 day') d WHERE NOT EXISTS(SELECT 1 FROM ccpun_admin.marketing_report_manifest m JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE m.report=p_report AND m.complete AND b.status='completed' AND m.resource_scope<>'legacy-unverified' AND d::date BETWEEN m.period_start AND m.period_end))
$coverage$;
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_metric_record(p_metric text,p_current numeric,p_previous numeric,p_complete boolean,p_previous_complete boolean,p_evidence text) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,ccpun_admin AS $metric$
 SELECT jsonb_build_object('metric',p_metric,'current',CASE WHEN p_complete THEN coalesce(p_current,0) ELSE p_current END,'previous',CASE WHEN p_previous_complete THEN coalesce(p_previous,0) ELSE NULL END,'absoluteChange',CASE WHEN p_complete AND p_previous_complete THEN coalesce(p_current,0)-coalesce(p_previous,0) ELSE NULL END,'percentageChange',CASE WHEN p_complete AND p_previous_complete AND p_previous>0 THEN round((coalesce(p_current,0)-p_previous)*100/p_previous,2) ELSE NULL END,'sampleStatus',CASE WHEN NOT p_complete OR coalesce(p_current,0)<r.minimum_volume THEN 'insufficient_data' WHEN NOT p_previous_complete OR coalesce(p_previous,0)<r.minimum_previous THEN 'low' ELSE 'sufficient' END,'coverageStatus',CASE WHEN p_complete AND p_previous_complete THEN 'complete' WHEN p_complete THEN 'insufficient_history' ELSE 'partial' END,'freshnessStatus','see_source_health','threshold',r.minimum_volume,'unit',CASE WHEN p_metric LIKE '%sessions' THEN 'sessions' WHEN p_metric LIKE '%clicks' THEN 'clicks' WHEN p_metric='search_impressions' THEN 'impressions' WHEN p_metric='search_ctr' THEN 'percent' WHEN p_metric='search_average_position' THEN 'position' WHEN p_metric='social_views' THEN 'views' WHEN p_metric='social_reach' THEN 'native_reach' WHEN p_metric LIKE 'social_%' THEN 'native_counter' ELSE 'events' END,'evidenceRef',p_evidence) FROM ccpun_admin.marketing_metric_rule r WHERE metric=p_metric
$metric$;
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_lifecycle_rule (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),new_days integer NOT NULL CHECK(new_days BETWEEN 7 AND 90),history_days integer NOT NULL CHECK(history_days BETWEEN 84 AND 365),change_percent numeric NOT NULL CHECK(change_percent BETWEEN 1 AND 100),version text NOT NULL);
INSERT INTO ccpun_admin.marketing_lifecycle_rule VALUES(true,28,84,25,'lifecycle-v1') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_lifecycle(p_asset text,p_url text,p_published timestamptz,p_end date) RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog,ccpun_admin AS $lifecycle$
 WITH rule AS(SELECT * FROM ccpun_admin.marketing_lifecycle_rule WHERE singleton),periods AS(SELECT sum(value) FILTER(WHERE day BETWEEN p_end-27 AND p_end) current,sum(value) FILTER(WHERE day BETWEEN p_end-55 AND p_end-28) previous,sum(value) FILTER(WHERE day BETWEEN p_end-83 AND p_end-56) older FROM ccpun_admin.marketing_daily_metric WHERE metric='organic_sessions' AND ccpun_admin.marketing_canonical_url(asset_url)=p_url AND day BETWEEN p_end-83 AND p_end),threshold AS(SELECT minimum_volume FROM ccpun_admin.marketing_metric_rule WHERE metric='organic_sessions')
 SELECT CASE WHEN p_published::date>p_end-new_days THEN 'new' WHEN NOT ccpun_admin.marketing_coverage('ga4-daily-organic',p_end-history_days+1,p_end) OR least(current,previous,older)<minimum_volume THEN 'insufficient_history' WHEN current<previous*(1-change_percent/100) AND previous<older*(1-change_percent/100) THEN CASE WHEN older>=minimum_volume*3 THEN 'refresh_candidate' ELSE 'declining' END WHEN current>previous*(1+change_percent/100) THEN 'growing' WHEN abs(current-previous)<=previous*change_percent/100 AND abs(previous-older)<=older*change_percent/100 THEN 'evergreen' ELSE 'mature' END FROM rule CROSS JOIN periods CROSS JOIN threshold
$lifecycle$;
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_content_metrics(p_cs date,p_ce date,p_ps date,p_pe date) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,ccpun_admin AS $content_metrics$
 WITH totals AS(SELECT metric,ccpun_admin.marketing_canonical_url(asset_url) url,sum(value) FILTER(WHERE day BETWEEN p_cs AND p_ce) current,sum(value) FILTER(WHERE day BETWEEN p_ps AND p_pe) previous FROM ccpun_admin.marketing_daily_metric WHERE day BETWEEN p_ps AND p_ce GROUP BY metric,2),search AS(SELECT ccpun_admin.marketing_canonical_url(page) url,sum(clicks) FILTER(WHERE day BETWEEN p_cs AND p_ce) clicks_current,sum(impressions) FILTER(WHERE day BETWEEN p_cs AND p_ce) impressions_current,sum(average_position*impressions) FILTER(WHERE day BETWEEN p_cs AND p_ce) weighted_current,sum(clicks) FILTER(WHERE day BETWEEN p_ps AND p_pe) clicks_previous,sum(impressions) FILTER(WHERE day BETWEEN p_ps AND p_pe) impressions_previous,sum(average_position*impressions) FILTER(WHERE day BETWEEN p_ps AND p_pe) weighted_previous FROM ccpun_admin.marketing_gsc_current WHERE report='gsc-daily-page' AND day BETWEEN p_ps AND p_ce GROUP BY 1),diagnostics AS(SELECT url,'search_ctr' metric,clicks_current/nullif(impressions_current,0)*100 current,clicks_previous/nullif(impressions_previous,0)*100 previous,impressions_current,impressions_previous FROM search UNION ALL SELECT url,'search_average_position',weighted_current/nullif(impressions_current,0),weighted_previous/nullif(impressions_previous,0),impressions_current,impressions_previous FROM search),facts AS(SELECT t.*,a.asset_id,a.title,a.category,a.topic,a.published_at,ccpun_admin.marketing_metric_record(metric,current,previous,ccpun_admin.marketing_coverage(CASE WHEN metric='organic_sessions' THEN 'ga4-daily-organic' WHEN metric LIKE 'search_%' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,p_cs,p_ce),ccpun_admin.marketing_coverage(CASE WHEN metric='organic_sessions' THEN 'ga4-daily-organic' WHEN metric LIKE 'search_%' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,p_ps,p_pe),'content:'||metric||':'||coalesce(a.asset_id,t.url)) evidence FROM totals t LEFT JOIN ccpun_admin.marketing_asset_alias al ON al.url=t.url LEFT JOIN ccpun_admin.marketing_asset a USING(asset_id) WHERE t.url IS NOT NULL UNION ALL SELECT d.metric,d.url,d.current,d.previous,a.asset_id,a.title,a.category,a.topic,a.published_at,ccpun_admin.marketing_metric_record(d.metric,d.current,d.previous,ccpun_admin.marketing_coverage('gsc-daily-page',p_cs,p_ce),ccpun_admin.marketing_coverage('gsc-daily-page',p_ps,p_pe),'content:'||d.metric||':'||coalesce(a.asset_id,d.url))||jsonb_build_object('current',d.current,'previous',CASE WHEN ccpun_admin.marketing_coverage('gsc-daily-page',p_ps,p_pe) THEN d.previous ELSE NULL END,'sampleStatus',CASE WHEN coalesce(d.impressions_current,0)<100 OR NOT ccpun_admin.marketing_coverage('gsc-daily-page',p_cs,p_ce) THEN 'insufficient_data' WHEN coalesce(d.impressions_previous,0)<100 OR NOT ccpun_admin.marketing_coverage('gsc-daily-page',p_ps,p_pe) THEN 'low' ELSE 'sufficient' END,'currentDenominator',d.impressions_current,'previousDenominator',d.impressions_previous) FROM diagnostics d LEFT JOIN ccpun_admin.marketing_asset_alias al ON al.url=d.url LEFT JOIN ccpun_admin.marketing_asset a USING(asset_id) WHERE d.url IS NOT NULL),assets AS(SELECT coalesce(asset_id,'unmapped:'||url) asset_id,url,coalesce(title,url) title,category,topic,published_at,jsonb_agg(evidence ORDER BY metric) metrics FROM facts GROUP BY 1,2,3,4,5,6 ORDER BY 1 LIMIT 2000)
 SELECT coalesce(jsonb_agg(jsonb_build_object('assetId',asset_id,'url',url,'title',title,'category',category,'topic',topic,'publishedAt',published_at,'mappingStatus',CASE WHEN asset_id LIKE 'unmapped:%' THEN 'unmapped' ELSE 'mapped' END,'lifecycle',ccpun_admin.marketing_lifecycle(asset_id,url,published_at,p_ce),'metrics',metrics) ORDER BY asset_id),'[]') FROM assets
$content_metrics$;
CREATE OR REPLACE FUNCTION ccpun_admin.admin_read_marketing(p_key text DEFAULT 'rolling_7',p_now timestamptz DEFAULT now()) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $read$
DECLARE w jsonb; cs date;ce date;ps date;pe date;board jsonb;boards jsonb:='[]';kpis jsonb;health jsonb;manifest jsonb;actions jsonb;opportunities jsonb;rule record;content jsonb;extra jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM ccpun_admin.marketing_report_manifest m JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.status='completed' AND m.collected_at>p_now) THEN RAISE EXCEPTION 'MARKETING_CUTOFF_SUPERSEDED'; END IF;
 -- One common mature cutoff; dates remain native provider dates, not relabelled time instants.
 w:=ccpun_admin.marketing_window(p_key,least((p_now AT TIME ZONE 'America/Los_Angeles')::date-3,(p_now AT TIME ZONE ccpun_admin.admin_marketing_calendar('ga4'))::date-1));cs:=(w->>'currentStart')::date;ce:=(w->>'currentEnd')::date;ps:=(w->>'previousStart')::date;pe:=(w->>'previousEnd')::date;
 SELECT coalesce(jsonb_agg(ccpun_admin.marketing_metric_record(r.metric,(SELECT sum(value) FROM ccpun_admin.marketing_daily_metric WHERE metric=r.metric AND day BETWEEN cs AND ce),(SELECT sum(value) FROM ccpun_admin.marketing_daily_metric WHERE metric=r.metric AND day BETWEEN ps AND pe),ccpun_admin.marketing_coverage(CASE WHEN r.metric='organic_sessions' THEN 'ga4-daily-organic' WHEN r.metric LIKE 'search_%' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,cs,ce),ccpun_admin.marketing_coverage(CASE WHEN r.metric='organic_sessions' THEN 'ga4-daily-organic' WHEN r.metric LIKE 'search_%' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,ps,pe),'kpi:'||r.metric) ORDER BY r.metric),'[]') INTO kpis FROM ccpun_admin.marketing_metric_rule r WHERE r.metric IN('organic_sessions','search_clicks','search_impressions','line_clicks','calculator_complete');
 FOR rule IN SELECT * FROM ccpun_admin.marketing_metric_rule WHERE metric IN('organic_sessions','search_clicks','line_clicks','calculator_complete') LOOP
  WITH totals AS(SELECT ccpun_admin.marketing_canonical_url(asset_url) url,sum(value) FILTER(WHERE day BETWEEN cs AND ce) current,sum(value) FILTER(WHERE day BETWEEN ps AND pe) previous FROM ccpun_admin.marketing_daily_metric WHERE metric=rule.metric AND day BETWEEN ps AND ce GROUP BY 1), ranked AS(SELECT t.*,a.asset_id,a.title,a.category,a.published_at,row_number() OVER(ORDER BY t.current DESC NULLS LAST,t.url) rank FROM totals t LEFT JOIN ccpun_admin.marketing_asset_alias al ON al.url=t.url LEFT JOIN ccpun_admin.marketing_asset a USING(asset_id) WHERE t.current IS NOT NULL AND t.url IS NOT NULL)
  SELECT coalesce(jsonb_agg(ccpun_admin.marketing_metric_record(rule.metric,current,previous,ccpun_admin.marketing_coverage(CASE WHEN rule.metric='organic_sessions' THEN 'ga4-daily-organic' WHEN rule.metric='search_clicks' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,cs,ce),ccpun_admin.marketing_coverage(CASE WHEN rule.metric='organic_sessions' THEN 'ga4-daily-organic' WHEN rule.metric='search_clicks' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,ps,pe),'content:'||rule.metric||':'||coalesce(asset_id,url))||jsonb_build_object('rank',rank,'assetId',coalesce(asset_id,'unmapped:'||url),'title',coalesce(title,url),'url',url,'category',category,'publishedAt',published_at,'mappingStatus',CASE WHEN asset_id IS NULL THEN 'unmapped' ELSE 'mapped' END,'lifecycle',CASE WHEN published_at::date>=cs-28 THEN 'new' ELSE 'insufficient_history' END) ORDER BY rank),'[]') INTO board FROM ranked WHERE rank<=10;
  boards:=boards||jsonb_build_array(jsonb_build_object('id',rule.metric,'title',CASE rule.metric WHEN 'organic_sessions' THEN 'Top Organic Content' WHEN 'search_clicks' THEN 'Top Search Content' WHEN 'line_clicks' THEN 'Top LINE Intent Activity' ELSE 'Top Calculator Completion Activity' END,'metric',rule.metric,'basis',rule.metric||' descending; URL tie-break; provider-native daily facts; event counts are repeatable','platform',NULL,'rows',board));
 END LOOP;
 -- Social: native snapshot values for posts published in period, never weekly Reach/activity deltas.
 FOR rule IN SELECT unnest(ARRAY['Facebook','Instagram']) AS metric LOOP
  WITH latest AS(SELECT DISTINCT ON(platform,object_id) * FROM ccpun_admin.marketing_social_unified s WHERE captured_at<=p_now ORDER BY platform,object_id,captured_at DESC),ranked AS(SELECT *,row_number() OVER(ORDER BY views DESC,object_id) rank FROM latest WHERE platform=rule.metric AND published_at::date BETWEEN cs AND ce AND views IS NOT NULL)
  SELECT coalesce(jsonb_agg(ccpun_admin.marketing_metric_record('social_views',views,NULL,true,false,'social:'||platform||':'||object_id)||jsonb_build_object('rank',rank,'assetId','social:'||platform||':'||object_id,'title',object_id,'url',url,'category',content_type,'publishedAt',published_at,'mappingStatus','unmapped','lifecycle','new') ORDER BY rank),'[]') INTO board FROM ranked WHERE rank<=10;
  boards:=boards||jsonb_build_array(jsonb_build_object('id','social_'||lower(rule.metric),'title','Top '||rule.metric||' published posts · snapshot views','metric','social_views','basis','Posts published in selected period, ranked by latest native cumulative views; NOT activity during period','platform',rule.metric,'rows',board));
 END LOOP;
 WITH latest AS(SELECT DISTINCT ON(report) m.* FROM ccpun_admin.marketing_report_manifest m JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.status='completed' AND m.collected_at<=p_now ORDER BY report,m.collected_at DESC),attempt AS(SELECT DISTINCT ON(source) source,status,error_category,attempted_at FROM ccpun_admin.analytics_daily_batch WHERE attempted_at<=p_now ORDER BY source,attempted_at DESC)
 SELECT coalesce(jsonb_agg(jsonb_build_object('source',b.source,'report',m.report,'sourceAsOf',m.source_as_of,'collectedAt',m.collected_at,'lastSuccess',m.collected_at,'lastError',a.error_category,'expectedLagDays',CASE b.source WHEN 'gsc' THEN 3 ELSE 1 END,'status',CASE WHEN a.status='failed' THEN 'failed' WHEN m.source_as_of IS NULL THEN 'unknown' WHEN (p_now AT TIME ZONE 'Asia/Bangkok')::date-m.source_as_of_date>CASE b.source WHEN 'gsc' THEN 5 ELSE 3 END THEN 'stale' WHEN b.source='gsc' THEN 'expected_lag' ELSE 'fresh' END,'coverageStart',m.period_start,'coverageEnd',m.period_end,'timezone',m.source_timezone,'limitations',m.limitations) ORDER BY m.report),'[]') INTO health FROM latest m JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) LEFT JOIN attempt a USING(source);
 SELECT coalesce(jsonb_agg(jsonb_build_object('batchId',batch_id,'report',report,'rawHash',raw_sha256,'periodStart',period_start,'periodEnd',period_end,'sourceAsOf',source_as_of,'collectedAt',collected_at,'timezone',source_timezone,'limitations',limitations)),'[]') INTO manifest FROM ccpun_admin.marketing_report_manifest WHERE collected_at<=p_now AND ((period_start<=ce AND period_end>=ps) OR period_start IS NULL);
 content:=ccpun_admin.marketing_content_metrics(cs,ce,ps,pe);
 WITH latest AS(SELECT DISTINCT ON(platform,object_id) * FROM ccpun_admin.marketing_social_unified WHERE captured_at<=p_now ORDER BY platform,object_id,captured_at DESC),assets AS(SELECT * FROM latest ORDER BY platform,object_id LIMIT 2000)
 SELECT coalesce(jsonb_agg(jsonb_build_object('assetId','social:'||platform||':'||object_id,'title',object_id,'url',coalesce(url,''),'category',content_type,'topic',NULL,'publishedAt',published_at,'mappingStatus','unmapped','lifecycle',CASE WHEN published_at::date>=cs-28 THEN 'new' ELSE 'insufficient_history' END,'metrics',(SELECT jsonb_agg(ccpun_admin.marketing_metric_record(metric,value,NULL,false,false,'social:'||platform||':'||object_id||':'||metric)||jsonb_build_object('freshnessStatus',CASE WHEN captured_at>=p_now-interval '3 days' THEN 'fresh' ELSE 'stale' END,'coverageStatus','native_snapshot_not_period_activity','unit',CASE WHEN metric='social_reach' THEN 'native_reach' ELSE 'native_counter' END)) FROM (VALUES('social_views',views),('social_reach',reach),('social_interactions',interactions),('social_shares',shares),('social_saves',saves)) m(metric,value))) ORDER BY platform,object_id),'[]') INTO extra FROM assets;
 content:=content||extra;
 FOR rule IN SELECT unnest(ARRAY['growing','declining','new','evergreen']) AS metric LOOP
  WITH rows AS(SELECT c,(SELECT m FROM jsonb_array_elements(c->'metrics') m WHERE m->>'metric'='organic_sessions') m FROM jsonb_array_elements(content) c),ranked AS(SELECT *,row_number() OVER(ORDER BY CASE WHEN rule.metric='growing' THEN (m->>'absoluteChange')::numeric WHEN rule.metric='declining' THEN -(m->>'absoluteChange')::numeric ELSE (m->>'current')::numeric END DESC,c->>'assetId') rank FROM rows WHERE m IS NOT NULL AND CASE WHEN rule.metric='new' THEN c->>'lifecycle'='new' WHEN rule.metric='evergreen' THEN c->>'lifecycle'='evergreen' WHEN rule.metric='growing' THEN m->>'sampleStatus'='sufficient' AND (m->>'percentageChange')::numeric>=25 WHEN rule.metric='declining' THEN m->>'sampleStatus'='sufficient' AND (m->>'percentageChange')::numeric<=-25 ELSE false END) SELECT coalesce(jsonb_agg(m||jsonb_build_object('rank',rank,'assetId',c->>'assetId','url',c->>'url','title',c->>'title','category',c->>'category','publishedAt',c->>'publishedAt','mappingStatus',c->>'mappingStatus','lifecycle',c->>'lifecycle') ORDER BY rank),'[]') INTO extra FROM ranked WHERE rank<=10;
  boards:=boards||jsonb_build_array(jsonb_build_object('id',rule.metric,'title','Top '||rule.metric||' organic content','metric','organic_sessions','basis',CASE WHEN rule.metric IN('growing','declining') THEN 'Valid comparable period change after minimum-volume threshold; absolute change ranking' ELSE 'Organic sessions; new/lifecycle eligibility from versioned deterministic rules' END,'platform',NULL,'rows',extra));
 END LOOP;
 SELECT coalesce(jsonb_agg(ccpun_admin.marketing_action_json(a.*) ORDER BY a.updated_at DESC),'[]') INTO actions FROM(SELECT * FROM ccpun_admin.marketing_action ORDER BY updated_at DESC LIMIT 100) a;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id','decline:'||(x->>'metric'),'area','performance','assetId',NULL,'title','Investigate material decline: '||(x->>'metric'),'priority','high','evidenceRefs',jsonb_build_array(x->>'evidenceRef'),'recommendedAction','investigation','confidence','medium','reason','Comparable covered periods exceed minimum volumes; decline is an observation, not a causal conclusion')),'[]') INTO opportunities FROM jsonb_array_elements(kpis) x JOIN ccpun_admin.marketing_metric_rule r ON r.metric=x->>'metric' WHERE x->>'sampleStatus'='sufficient' AND (x->>'percentageChange')::numeric<=-r.decline_percent;
 SELECT opportunities||coalesce(jsonb_agg(jsonb_build_object('id','health:'||(h->>'report'),'area','data_health','assetId',NULL,'title','Check source freshness: '||(h->>'report'),'priority','medium','evidenceRefs',jsonb_build_array('health:'||(h->>'report')),'recommendedAction','investigation','confidence','low','reason','Source is stale or latest attempt failed; qualify recommendations until current evidence is available')),'[]') INTO opportunities FROM jsonb_array_elements(health) h WHERE h->>'status' IN('stale','failed');
 RETURN jsonb_build_object('state','ready','version','marketing-v1','generatedAt',p_now,'window',w,'kpis',kpis,'contentPerformance',content,'campaigns',(SELECT coalesce(jsonb_agg(jsonb_build_object('sourceMedium',source_medium,'campaign',campaign,'landingUrl',url,'assetId',asset_id,'sessions',sessions,'engagedSessions',engaged,'keyEvents',key_events,'coverageStatus',CASE WHEN ccpun_admin.marketing_coverage('ga4-session-performance',cs,ce) THEN 'complete' ELSE 'partial' END,'periodStart',cs,'periodEnd',ce) ORDER BY sessions DESC,url),'[]') FROM(SELECT f.source_medium,f.campaign,ccpun_admin.marketing_canonical_url(f.landing_page) url,al.asset_id,sum(f.sessions) sessions,sum(f.engaged_sessions) engaged,sum(f.key_events) key_events FROM ccpun_admin.marketing_ga4_current f LEFT JOIN ccpun_admin.marketing_asset_alias al ON al.url=ccpun_admin.marketing_canonical_url(f.landing_page) WHERE f.report='ga4-session-performance' AND f.day BETWEEN cs AND ce GROUP BY 1,2,3,4 ORDER BY sum(f.sessions) DESC LIMIT 2000) c),'benchmarks',(SELECT coalesce(jsonb_agg(jsonb_build_object('positionBand',position_band,'cohortSize',cohort_size,'medianCtr',median_ctr,'definition',definition)),'[]') FROM ccpun_admin.marketing_search_benchmark),'leaderboards',boards,'trend',(SELECT coalesce(jsonb_agg(jsonb_build_object('date',day,'metric',metric,'value',value) ORDER BY day,metric),'[]') FROM(SELECT day,metric,sum(value) value FROM ccpun_admin.marketing_daily_metric WHERE day BETWEEN cs AND ce GROUP BY day,metric) t),'funnel',jsonb_build_object('mode','activity-only','steps',(SELECT coalesce(jsonb_agg(jsonb_build_object('event',event_name,'count',count,'status','repeatable_event_count')),'[]') FROM(SELECT event_name,sum(event_count) count FROM ccpun_admin.marketing_event_current WHERE report='ga4-marketing-events' AND day BETWEEN cs AND ce GROUP BY event_name) e),'limitation','Behavioral events are not confirmed leads; no cohort/session sequence, so conversion/drop-off rates and downstream outcomes are unavailable'),'health',health,'opportunities',opportunities,'actions',actions,'manifest',manifest,'notes',jsonb_build_array('Numerical facts use latest native-key provider revisions; overlapping rolling reports are never summed.','Blank is unavailable; zero requires a successfully covered report window.','GA4 distinct users and native Reach are nonadditive; no summed distinct-user metric is emitted.','North Star qualified conversations, appointments and revenue are unavailable without governed business outcomes.','Growth/decline, evergreen lifecycle and benchmark confidence require sufficient comparable history.','MTD uses equivalent elapsed days; cross-source native-date/timezone alignment is disclosed.','Actions are managed in Admin/Neon; bounded versioned Sheet imports preserve human fields and conflicts.'));
END $read$;
CREATE OR REPLACE FUNCTION ccpun_admin.marketing_action_json(a ccpun_admin.marketing_action) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,ccpun_admin AS $action_json$
 WITH periods AS(SELECT (a.executed_at AT TIME ZONE 'Asia/Bangkok')::date e),vals AS(SELECT a.baseline_value baseline,sum(value) FILTER(WHERE day BETWEEN e+1 AND e+a.measurement_days) result FROM ccpun_admin.marketing_daily_metric d CROSS JOIN periods WHERE d.metric=a.expected_metric AND EXISTS(SELECT 1 FROM ccpun_admin.marketing_asset_alias al WHERE al.asset_id=a.asset_id AND al.url=ccpun_admin.marketing_canonical_url(d.asset_url))),checks AS(SELECT a.baseline_covered AND a.executed_at IS NOT NULL AND (now() AT TIME ZONE 'Asia/Bangkok')::date-3>=e+a.measurement_days AND ccpun_admin.marketing_coverage(CASE a.expected_metric WHEN 'organic_sessions' THEN 'ga4-daily-organic' WHEN 'search_clicks' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,e-a.measurement_days,e+a.measurement_days) ready FROM periods)
 SELECT jsonb_build_object('id',a.action_id,'version',a.version,'assetId',a.asset_id,'priority',a.priority,'actionType',a.action_type,'description',a.description,'expectedMetric',a.expected_metric,'owner',a.owner,'status',a.status,'createdAt',a.created_at,'updatedAt',a.updated_at,'executedAt',a.executed_at,'measurementDays',a.measurement_days,'notes',a.notes,'hypothesis',a.hypothesis,'confounderNotes',a.confounder_notes,'baseline',CASE WHEN ready THEN baseline ELSE NULL END,'result',CASE WHEN ready THEN result ELSE NULL END,'absoluteChange',CASE WHEN ready THEN result-baseline ELSE NULL END,'percentageChange',CASE WHEN ready AND baseline>0 THEN round((result-baseline)*100/baseline,2) ELSE NULL END,'outcome',CASE WHEN NOT ready OR baseline IS NULL OR result IS NULL OR baseline=0 THEN 'inconclusive' WHEN result>baseline THEN 'improved_after' WHEN result<baseline THEN 'declined_after' ELSE 'inconclusive' END,'measurementStatus',CASE WHEN ready THEN 'covered_pre_post_observation_not_causality' ELSE 'awaiting_mature_complete_history' END) FROM vals CROSS JOIN checks
$action_json$;
CREATE OR REPLACE FUNCTION ccpun_admin.admin_save_marketing_action(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $save_action$
DECLARE a ccpun_admin.marketing_action;
BEGIN
 IF octet_length(p::text)>12000 OR (p->>'version')::integer<0 THEN RAISE EXCEPTION 'INVALID_MARKETING_ACTION'; END IF;
 IF p->>'id' IS NULL THEN
  IF (p->>'version')::integer<>0 THEN RAISE EXCEPTION 'MARKETING_ACTION_CONFLICT'; END IF;
  INSERT INTO ccpun_admin.marketing_action(asset_id,priority,action_type,description,expected_metric,owner,status,executed_at,measurement_days,notes,hypothesis,confounder_notes) VALUES(p->>'assetId',p->>'priority',p->>'actionType',p->>'description',p->>'expectedMetric',p->>'owner',p->>'status',(p->>'executedAt')::timestamptz,(p->>'measurementDays')::integer,p->>'notes',p->>'hypothesis',p->>'confounderNotes') RETURNING * INTO a;
 ELSE
  UPDATE ccpun_admin.marketing_action SET version=version+1,asset_id=p->>'assetId',priority=p->>'priority',action_type=p->>'actionType',description=p->>'description',expected_metric=p->>'expectedMetric',owner=p->>'owner',status=p->>'status',executed_at=(p->>'executedAt')::timestamptz,measurement_days=(p->>'measurementDays')::integer,notes=p->>'notes',hypothesis=p->>'hypothesis',confounder_notes=p->>'confounderNotes',updated_at=now() WHERE action_id=(p->>'id')::uuid AND version=(p->>'version')::integer AND (executed_at IS NULL OR (executed_at IS NOT DISTINCT FROM (p->>'executedAt')::timestamptz AND asset_id IS NOT DISTINCT FROM p->>'assetId' AND expected_metric=p->>'expectedMetric' AND measurement_days=(p->>'measurementDays')::integer)) RETURNING * INTO a;
  IF NOT FOUND THEN RAISE EXCEPTION 'MARKETING_ACTION_CONFLICT'; END IF;
 END IF;
 IF a.executed_at IS NOT NULL AND a.baseline_manifest IS NULL THEN
  UPDATE ccpun_admin.marketing_action SET baseline_value=(SELECT coalesce(sum(d.value),0) FROM ccpun_admin.marketing_daily_metric d WHERE d.metric=a.expected_metric AND d.day BETWEEN (a.executed_at AT TIME ZONE 'Asia/Bangkok')::date-a.measurement_days AND (a.executed_at AT TIME ZONE 'Asia/Bangkok')::date-1 AND EXISTS(SELECT 1 FROM ccpun_admin.marketing_asset_alias al WHERE al.asset_id=a.asset_id AND al.url=ccpun_admin.marketing_canonical_url(d.asset_url))),baseline_covered=a.asset_id IS NOT NULL AND a.expected_metric<>'social_views' AND ccpun_admin.marketing_coverage(CASE a.expected_metric WHEN 'organic_sessions' THEN 'ga4-daily-organic' WHEN 'search_clicks' THEN 'gsc-daily-page' ELSE 'ga4-content-events' END,(a.executed_at AT TIME ZONE 'Asia/Bangkok')::date-a.measurement_days,(a.executed_at AT TIME ZONE 'Asia/Bangkok')::date-1),baseline_manifest=(SELECT coalesce(jsonb_agg(jsonb_build_object('batchId',batch_id,'report',report,'rawHash',raw_sha256)),'[]') FROM ccpun_admin.marketing_report_manifest WHERE period_start<=(a.executed_at AT TIME ZONE 'Asia/Bangkok')::date-1 AND period_end>=(a.executed_at AT TIME ZONE 'Asia/Bangkok')::date-a.measurement_days) WHERE action_id=a.action_id RETURNING * INTO a;
 END IF;
 INSERT INTO ccpun_admin.marketing_action_revision VALUES(a.action_id,a.version,to_jsonb(a),now());
 RETURN ccpun_admin.marketing_action_json(a);
END $save_action$;
CREATE OR REPLACE FUNCTION ccpun_admin.admin_sync_marketing_identity(p jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $identity$
DECLARE x jsonb;alias jsonb; n integer:=0;
BEGIN
 IF jsonb_typeof(p)<>'array' OR jsonb_array_length(p)>2000 OR octet_length(p::text)>2000000 THEN RAISE EXCEPTION 'INVALID_MARKETING_IDENTITY'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p) LOOP
  IF x->>'assetId' IS NULL OR x->>'title' IS NULL OR length(x->>'title')>500 OR length(x->>'assetId')>200 OR x->>'canonicalUrl' !~ '^https://(ccpun\.com|blog\.ccpun\.com)/' THEN RAISE EXCEPTION 'INVALID_MARKETING_IDENTITY'; END IF;
  INSERT INTO ccpun_admin.marketing_asset VALUES(x->>'assetId',x->>'canonicalUrl',x->>'title',x->>'category',x->>'topic',x->>'searchIntent',x->>'contentType',(x->>'publishedAt')::timestamptz,x->>'status',x->>'revision',now()) ON CONFLICT(asset_id) DO UPDATE SET canonical_url=excluded.canonical_url,title=excluded.title,category=excluded.category,topic=excluded.topic,search_intent=excluded.search_intent,published_at=excluded.published_at,publication_status=excluded.publication_status,source_revision=excluded.source_revision,updated_at=now();
  FOR alias IN SELECT value FROM jsonb_array_elements(x->'aliases') LOOP
   IF alias->>'url' IS NULL OR alias->>'url' !~ '^https://(ccpun\.com|blog\.ccpun\.com)/' OR alias->>'url'~'[?#]' THEN RAISE EXCEPTION 'INVALID_MARKETING_ALIAS'; END IF;
   IF EXISTS(SELECT 1 FROM ccpun_admin.marketing_asset_alias WHERE url=alias->>'url' AND asset_id<>x->>'assetId') THEN RAISE EXCEPTION 'MARKETING_ALIAS_CONFLICT'; END IF;
   INSERT INTO ccpun_admin.marketing_asset_alias(url,asset_id,mapping_method) VALUES(alias->>'url',x->>'assetId',alias->>'method') ON CONFLICT(url) DO UPDATE SET updated_at=now();
  END LOOP;n:=n+1;
 END LOOP;RETURN n;
END $identity$;
CREATE OR REPLACE FUNCTION ccpun_admin.admin_marketing_calendar(p_source text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $calendar$
 SELECT CASE WHEN p_source='gsc' THEN 'America/Los_Angeles' ELSE coalesce((SELECT m.source_timezone FROM ccpun_admin.marketing_report_manifest m JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.source='ga4' AND b.status='completed' AND m.source_timezone IS NOT NULL ORDER BY m.collected_at DESC LIMIT 1),'America/Los_Angeles') END
$calendar$;
CREATE OR REPLACE FUNCTION ccpun_admin.admin_begin_marketing_window(p_source text,p_start date,p_end date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $begin_window$
DECLARE b ccpun_admin.analytics_daily_batch; claimed boolean:=false; k text:='marketing-v1:'||p_start::text||':'||p_end::text; today date:=(now() AT TIME ZONE 'Asia/Bangkok')::date;
BEGIN
 IF p_source NOT IN('gsc','ga4') OR p_start>p_end OR p_end-p_start>55 OR p_end>(now() AT TIME ZONE ccpun_admin.admin_marketing_calendar(p_source))::date-(CASE WHEN p_source='gsc' THEN 3 ELSE 1 END) OR (p_source='gsc' AND p_start<(today-interval '16 months')::date) OR p_start<today-1095 THEN RAISE EXCEPTION 'INVALID_MARKETING_WINDOW'; END IF;
 INSERT INTO ccpun_admin.analytics_daily_batch(source,collection_date,collection_key,status) VALUES(p_source,today,k,'running') ON CONFLICT DO NOTHING RETURNING * INTO b;
 IF FOUND THEN claimed:=true;ELSE SELECT * INTO b FROM ccpun_admin.analytics_daily_batch WHERE source=p_source AND collection_date=today AND collection_key=k FOR UPDATE;
 IF b.status<>'completed' AND b.attempt<2 AND (b.status='failed' OR b.attempted_at<now()-interval '5 minutes') THEN UPDATE ccpun_admin.analytics_daily_batch SET status='running',attempt=attempt+1,attempted_at=now(),error_category=NULL WHERE batch_id=b.batch_id RETURNING * INTO b;claimed:=true; END IF;END IF;
 RETURN jsonb_build_object('status',CASE WHEN claimed THEN 'claimed' ELSE b.status END,'batchId',b.batch_id,'attempt',b.attempt);
END $begin_window$;
CREATE OR REPLACE VIEW ccpun_admin.marketing_social_unified AS
 SELECT s.platform,s.object_id,s.captured_at,s.published_at,s.url,s.content_type,s.views,s.reach,s.interactions,s.shares,s.saves,'analytics-batch:'||s.batch_id::text provenance_ref FROM ccpun_admin.marketing_social_snapshot s JOIN ccpun_admin.analytics_daily_batch b USING(batch_id) WHERE b.status='completed'
 UNION ALL SELECT CASE c.platform WHEN 'facebook' THEN 'Facebook' ELSE 'Instagram' END,c.provider_object_id,s.fetched_at,c.published_at_utc,c.permalink,c.provider_media_type,NULL::numeric,p.reach,NULL::numeric,p.shares,p.saves,'social-mart:'||s.id::text FROM ccpun_social.social_provider_metric_snapshot s JOIN ccpun_social.marketing_content_current c ON c.content_id=s.content_id JOIN ccpun_social.post_performance_snapshot p ON p.snapshot_id=s.id WHERE c.platform IN('facebook','instagram');
CREATE OR REPLACE VIEW ccpun_admin.marketing_search_benchmark AS
 WITH pages AS(SELECT page,CASE WHEN sum(impressions)>0 THEN sum(average_position*impressions)/sum(impressions) END position,sum(clicks)/nullif(sum(impressions),0)*100 ctr,sum(impressions) impressions FROM ccpun_admin.marketing_gsc_current WHERE report='gsc-daily-page' AND day BETWEEN (now() AT TIME ZONE 'America/Los_Angeles')::date-59 AND (now() AT TIME ZONE 'America/Los_Angeles')::date-4 GROUP BY page),bands AS(SELECT *,CASE WHEN position<4 THEN '1-3' WHEN position<11 THEN '4-10' ELSE '11+' END position_band FROM pages WHERE impressions>=100)
 SELECT position_band,count(*) cohort_size,CASE WHEN count(*)>=20 THEN percentile_cont(0.5) WITHIN GROUP(ORDER BY ctr) END median_ctr,'page-scope:56d:100-impressions:20-pages:v1' definition FROM bands GROUP BY position_band;
CREATE TABLE IF NOT EXISTS ccpun_admin.marketing_sheet_action_ref (spreadsheet_id text NOT NULL CHECK(spreadsheet_id='1zpXXHuQ152wSZXdHb0yFJPVcdQiGOHvz4Yhxrmjdo-o'),import_key text NOT NULL CHECK(import_key~'^[A-Za-z0-9:_-]{1,120}$'),action_id uuid NOT NULL REFERENCES ccpun_admin.marketing_action(action_id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(spreadsheet_id,import_key));
CREATE OR REPLACE FUNCTION ccpun_admin.admin_import_marketing_actions(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,ccpun_admin AS $import_actions$
DECLARE row jsonb; a ccpun_admin.marketing_action;output jsonb:='[]';saved jsonb;linked uuid;same boolean;conflicts integer:=0;
BEGIN
 IF p->>'spreadsheetId' IS DISTINCT FROM '1zpXXHuQ152wSZXdHb0yFJPVcdQiGOHvz4Yhxrmjdo-o' OR jsonb_typeof(p->'rows')<>'array' OR jsonb_array_length(p->'rows')>100 OR octet_length(p::text)>1200000 THEN RAISE EXCEPTION 'INVALID_MARKETING_SHEET_IMPORT'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('ccpun_admin:marketing-action-sheet-import'));
 FOR row IN SELECT value FROM jsonb_array_elements(p->'rows') LOOP
  BEGIN
   IF row->>'importKey' !~ '^[A-Za-z0-9:_-]{1,120}$' THEN RAISE EXCEPTION 'INVALID_MARKETING_IMPORT_KEY'; END IF;
   linked:=NULL;SELECT action_id INTO linked FROM ccpun_admin.marketing_sheet_action_ref WHERE spreadsheet_id=p->>'spreadsheetId' AND import_key=row->>'importKey';
   SELECT * INTO a FROM ccpun_admin.marketing_action WHERE action_id=coalesce((row->>'id')::uuid,linked) FOR UPDATE;
   IF FOUND THEN
    same:=a.asset_id IS NOT DISTINCT FROM row->>'assetId' AND a.priority=row->>'priority' AND a.action_type=row->>'actionType' AND a.description=row->>'description' AND a.expected_metric=row->>'expectedMetric' AND a.owner=row->>'owner' AND a.status=row->>'status' AND a.executed_at IS NOT DISTINCT FROM (row->>'executedAt')::timestamptz AND a.measurement_days=(row->>'measurementDays')::integer AND a.notes=row->>'notes' AND a.hypothesis=row->>'hypothesis' AND a.confounder_notes=row->>'confounderNotes';
    IF same THEN output:=output||jsonb_build_array(jsonb_build_object('importKey',row->>'importKey','id',a.action_id,'version',a.version,'status','unchanged'));CONTINUE;END IF;
    IF row->>'id' IS NULL OR a.version<>(row->>'version')::integer OR (linked IS NOT NULL AND linked<>a.action_id) THEN RAISE EXCEPTION 'MARKETING_ACTION_CONFLICT'; END IF;
   ELSIF row->>'id' IS NOT NULL THEN RAISE EXCEPTION 'MARKETING_ACTION_CONFLICT';END IF;
   saved:=ccpun_admin.admin_save_marketing_action(row-'importKey');
   INSERT INTO ccpun_admin.marketing_sheet_action_ref(spreadsheet_id,import_key,action_id) VALUES(p->>'spreadsheetId',row->>'importKey',(saved->>'id')::uuid) ON CONFLICT DO NOTHING;
   output:=output||jsonb_build_array(jsonb_build_object('importKey',row->>'importKey','id',saved->>'id','version',saved->'version','status',CASE WHEN row->>'id' IS NULL THEN 'created' ELSE 'updated' END));
  EXCEPTION WHEN OTHERS THEN conflicts:=conflicts+1;output:=output||jsonb_build_array(jsonb_build_object('importKey',row->>'importKey','status',CASE WHEN SQLERRM LIKE '%MARKETING_ACTION_CONFLICT%' THEN 'conflict' ELSE 'rejected' END));END;
 END LOOP;RETURN jsonb_build_object('status',CASE WHEN conflicts>0 THEN 'needs-review' ELSE 'completed' END,'preserveActionPlan',conflicts>0,'conflicts',conflicts,'results',output);
END $import_actions$;
REVOKE ALL ON ccpun_admin.marketing_asset,ccpun_admin.marketing_asset_alias,ccpun_admin.marketing_report_manifest,ccpun_admin.marketing_gsc_daily,ccpun_admin.marketing_ga4_acquisition_daily,ccpun_admin.marketing_ga4_event_daily,ccpun_admin.marketing_social_snapshot,ccpun_admin.marketing_metric_rule,ccpun_admin.marketing_action,ccpun_admin.marketing_action_revision,ccpun_admin.marketing_gsc_current,ccpun_admin.marketing_ga4_current,ccpun_admin.marketing_event_current,ccpun_admin.marketing_daily_metric,ccpun_admin.marketing_social_unified,ccpun_admin.marketing_search_benchmark,ccpun_admin.marketing_lifecycle_rule,ccpun_admin.marketing_sheet_action_ref FROM PUBLIC,ccpun_admin_runtime;
REVOKE ALL ON FUNCTION ccpun_admin.marketing_project_report(uuid,text,jsonb),ccpun_admin.marketing_report_trigger(),ccpun_admin.marketing_canonical_url(text),ccpun_admin.marketing_window(text,date),ccpun_admin.marketing_coverage(text,date,date),ccpun_admin.marketing_metric_record(text,numeric,numeric,boolean,boolean,text),ccpun_admin.marketing_action_json(ccpun_admin.marketing_action),ccpun_admin.admin_read_marketing(text,timestamptz),ccpun_admin.admin_save_marketing_action(jsonb),ccpun_admin.admin_sync_marketing_identity(jsonb) FROM PUBLIC,ccpun_admin_runtime;
REVOKE ALL ON FUNCTION ccpun_admin.admin_import_marketing_actions(jsonb),ccpun_admin.admin_marketing_calendar(text),ccpun_admin.marketing_lifecycle(text,text,timestamptz,date),ccpun_admin.marketing_content_metrics(date,date,date,date),ccpun_admin.admin_begin_marketing_window(text,date,date) FROM PUBLIC,ccpun_admin_runtime;
GRANT EXECUTE ON FUNCTION ccpun_admin.admin_import_marketing_actions(jsonb),ccpun_admin.admin_marketing_calendar(text),ccpun_admin.admin_begin_marketing_window(text,date,date) TO ccpun_admin_runtime;
GRANT EXECUTE ON FUNCTION ccpun_admin.admin_read_marketing(text,timestamptz),ccpun_admin.admin_save_marketing_action(jsonb),ccpun_admin.admin_sync_marketing_identity(jsonb) TO ccpun_admin_runtime;
